mapper.select:
SELECT c.std_no AS stdNo, c.clause_no AS clauseNo, c.clause_title AS clauseTitle, c.content AS snippet, c.document_id AS docId, d.source_file AS sourceFile, d.source_type AS sourceType, d.ocr_derived AS ocrDerived, MATCH(c.content) AGAINST(#{query} IN BOOLEAN MODE) AS score FROM gb_clause c JOIN gb_document d ON d.id = c.document_id WHERE c.deleted = 0 AND d.deleted = 0 AND d.status = 1 AND MATCH(c.content) AGAINST(#{query} IN BOOLEAN MODE)
AND c.std_no LIKE CONCAT('%', #{stdNo}, '%')
ORDER BY (MATCH(c.clause_title) AGAINST(#{query} IN BOOLEAN MODE) > 0) DESC, score DESC, c.id ASC LIMIT #{topN}

SELECT c.std_no AS stdNo, c.clause_no AS clauseNo, c.clause_title AS clauseTitle, c.content AS snippet, c.document_id AS docId, d.source_file AS sourceFile, d.source_type AS sourceType, d.ocr_derived AS ocrDerived, MATCH(c.content) AGAINST(#{query}) AS score FROM gb_clause c JOIN gb_document d ON d.id = c.document_id WHERE c.deleted = 0 AND d.deleted = 0 AND d.status = 1 AND MATCH(c.content) AGAINST(#{query})
AND c.std_no LIKE CONCAT('%', #{stdNo}, '%')
ORDER BY (MATCH(c.clause_title) AGAINST(#{query}) > 0) DESC, score DESC, c.id ASC LIMIT #{topN}
